{
  "findings": [
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as the system requires a password to change settings and restricts content based on ESRB ratings.",
      "stance": "neutral",
      "quote": "The parental control level on your PS4 system to \"3\" prohibits users from playing any games with a level of \"4\" or higher."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that chat and voice chat are blocked by default, but can be turned off via the Chat/Message control.",
      "stance": "risk",
      "quote": "The default setting is \"Block\" meaning chat/message is restricted."
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "A parent reports that the app allows setting a monthly spending limit, with the default set to $0.00 to prevent purchases.",
      "stance": "mitigation",
      "quote": "The default value is set to \"$0.00\" meaning the Sub Account cannot make any purchases."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "A parent reports that the system collects no personal data beyond what is needed for parental controls, and settings can be reset to default.",
      "stance": "neutral",
      "quote": "If you select (Settings) > (System Settings) > [Restore Default Settings], you can reset the password to [0000]. Note that all other settings will also be restored to their default values."
    },
